 const reducedMotion=()=>{try{return !!window.VoidTheme?.state?.().effectiveReducedMotion||!!document.documentElement?.classList?.contains('vh-reduced-motion')||!!window.matchMedia?.('(prefers-reduced-motion: reduce)').matches;}catch{return false;}};
 const avatar=(value,{playable=false}={})=>{const profile=value&&typeof value==='object'?value:{avatar:value},url=posterURL(profile.avatarMedia),animated=playable?animationURL(profile.avatarMedia):null,mark=`<svg class="vp-avatar-mark" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path d="${paths[profile.avatar]||paths.moon}"/></svg>`;return url?`<span class="vp-avatar-image">${mark}<img src="${url}" alt="" loading="lazy" decoding="async" data-vp-photo${animated?` data-vp-animation="${animated}" data-vp-poster="${url}"`:''}></span>`:mark;};
 function stopGIFs(scope){for(const [card,record]of [...playingGIFs]){if(scope&&scope!==card&&!scope.contains?.(card))continue;playingGIFs.delete(card);record.observer?.disconnect();record.replacement?.disconnect();for(const image of record.images){if(image.isConnected===false)image.removeAttribute?.('src');else image.src=image.dataset.vpPoster;}if(record.button?.isConnected!==false){record.button.textContent='Play GIFs';record.button.setAttribute?.('aria-pressed','false');}}}
 function updateGIFControls(){if(reducedMotion())stopGIFs();for(const button of document.querySelectorAll?.('[data-vp-action="toggle-gifs"]')||[])button.disabled=reducedMotion();}
 function toggleGIFs(button){const card=button?.closest?.('.vp-card');if(!card)return;if(playingGIFs.has(card)){stopGIFs(card);return;}if(reducedMotion()||document.hidden){app.announce('GIFs stay still while motion is reduced or the app is hidden.');return;}const images=[...card.querySelectorAll('img[data-vp-animation]')].filter(image=>/^\/api\/media\/[a-f0-9]{64}\/animation$/.test(image.dataset.vpAnimation||'')&&image.dataset.vpAnimation===image.dataset.vpPoster+'/animation');if(!images.length)return app.announce('This GIF is unavailable. Reopen the profile and try again.');stopGIFs();const record={images,button,observer:null,replacement:null};playingGIFs.set(card,record);const stopOwn=()=>{if(playingGIFs.get(card)===record)stopGIFs(card);};for(const image of images)image.src=image.dataset.vpAnimation;button.textContent='Pause GIFs';button.setAttribute?.('aria-pressed','true');if(typeof IntersectionObserver==='function'){record.observer=new IntersectionObserver(entries=>{if(entries.some(entry=>!entry.isIntersecting))stopOwn();});record.observer.observe(card);}if(typeof MutationObserver==='function'){record.replacement=new MutationObserver(()=>{if(card.isConnected===false||images.some(image=>!card.contains?.(image)))stopOwn();});record.replacement.observe(document.body||document.documentElement,{childList:true,subtree:true});}}
 const art=(id,mini=false)=>window.VoidCosmetics?.art?.(id,mini)||avatar('spark');
 function sync(){const id=state().account?.id||'';if(id!==identity){stopGIFs();window.VoidProfileMedia?.disposeAll();identity=id;epoch++;writeVersion++;writeSerial++;cached=null;editor=null;dirty=false;busy=false;discardPrompt=false;}}
 function guard(){sync();const id=identity,version=epoch,parent=app.guard();return ()=>version===epoch&&id===state().account?.id&&parent();}
 const clean=p=>({displayName:p.displayName||'',bio:p.bio||'',status:p.status||'',avatar:p.avatar||'moon',banner:p.banner||'midnight',accent:p.accent||'ice',detailsVisibility:p.detailsVisibility||'shared',collectionVisibility:p.collectionVisibility||'shared',animationEnabled:!!p.animationEnabled,badgeOrder:p.badgeOrder||[],avatarMediaId:p.avatarMediaId||p.avatarMedia?.id||null,bannerMediaId:p.bannerMediaId||p.bannerMedia?.id||null});
