 async function openProfile(id=identity,compact=false){if(id===identity&&dirty)return beforeCloseDialog();const current=guard(),ticket=app.showDialog('Profile','', '<div id="vp-profile-result" role="status">Loading profile…</div>');try{const response=await app.request('/api/profiles/'+encodeURIComponent(id));if(!current()||ticket!==state().dialogGeneration)return;const node=$('vp-profile-result');if(node)node.innerHTML=profileCard(response.profile,{compact});if(id===identity)cached=response.profile;}catch(reason){if(current()&&ticket===state().dialogGeneration){const node=$('vp-profile-result');if(node)node.innerHTML='<p class="vp-private">This profile is unavailable to your account.</p>';}}}
