   await window.VoidProfileMedia.mountCrop({container:target,file,kind,isCurrent:selected,
    onApply:async blob=>{if(!selected())return;mediaState('uploading',`Uploading ${kind}. Wait for confirmation before saving your profile.`,kind);const asset=await window.VoidProfileMedia.upload({request:app.request,blob,kind,clientId,filename:kind+(blob.type==='image/gif'?'.gif':'.png'),isCurrent:selected});if(!selected())return;const oldId=snapshot.draft[kind+'MediaId'];snapshot.uploads.set(asset.id,asset);snapshot.draft[kind+'MediaId']=asset.id;if(asset.isGif===true||blob.type==='image/gif'){snapshot.draft.animationEnabled=true;const toggle=$('vp-editor')?.querySelector('[name="animationEnabled"]');if(toggle)toggle.checked=true;}snapshot.cropFile=null;snapshot.cropKind=null;snapshot.cropClientId=null;snapshot.mediaState={phase:'staged',kind,message:`${kind==='avatar'?'Avatar':'Banner'} uploaded privately. Choose Save profile to make it visible.`};if(failure)failure.textContent='';if(oldId&&snapshot.uploads.has(oldId)&&oldId!==asset.id){app.request('/api/media/'+oldId+'/cancel',{}).catch(()=>{});snapshot.uploads.delete(oldId);}updatePreview($('vp-editor'));app.announce('Image uploaded. Save profile to make it visible.');},
    onCancel:()=>{if(selected())cancelImage();},onError:reason=>{if(!selected())return;mediaState('error',`${reason.message||'The image could not be uploaded.'} Retry the upload below, choose another image, or Cancel image.`,kind);error(reason);}});
